function maxBlockSum(arr: number[], k: number): number {
  const go = (start: number): number => {
    if (start === arr.length) return 0;
    let best = 0, mx = 0;
    for (let j = 1; j <= k && start + j <= arr.length; j++) {
      mx = Math.max(mx, arr[start + j - 1]);
      best = Math.max(best, j * mx + go(start + j));
    }
    return best;
  };
  return go(0);
}

