    def maxBlockSum(self, arr: List[int], k: int) -> int:
        def go(start):
            if start == len(arr):
                return 0
            best = mx = 0
            for j in range(1, k + 1):
                if start + j > len(arr):
                    break
                mx = max(mx, arr[start + j - 1])
                best = max(best, j * mx + go(start + j))
            return best
        return go(0)

