function maxBlockSum(arr: number[], k: number): number {
  const n = arr.length;
  const best = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    let mx = 0;
    for (let j = 1; j <= Math.min(k, i); j++) {
      mx = Math.max(mx, arr[i - j]);
      best[i] = Math.max(best[i], best[i - j] + j * mx);
    }
  }
  return best[n];
}

